"use strict";
// Gap between toasts in pixels.
const DEFAULT_GAP = 12;

// Visual cap on rendered toasts; older ones fade out but keep running.
const DEFAULT_MAX_VISIBLE_TOAST = 3;

// The stately queue keeps every toast; visibility is applied per toast.
const DEFAULT_RAC_MAX_VISIBLE_TOAST = Number.MAX_SAFE_INTEGER;

// How much each toast behind the front one scales down.
const DEFAULT_SCALE_FACTOR = 0.05;

// Toast width in pixels.
const DEFAULT_TOAST_WIDTH = 460;

// Auto-dismiss timeout in milliseconds.
const DEFAULT_TOAST_TIMEOUT = 4000;

// How long a closing toast stays mounted for its exit animation, in milliseconds.
// Must be at least the longest exit transition in @heroui/styles, which is the
// frontmost toast's --toast-exit-duration (250ms); the rest is headroom.
const DEFAULT_EXIT_DURATION = 300;

// Modifiers match KeyboardEvent boolean props; other keys match event.code.
const DEFAULT_HOTKEY = ["altKey", "KeyT"];

export { DEFAULT_EXIT_DURATION, DEFAULT_GAP, DEFAULT_HOTKEY, DEFAULT_MAX_VISIBLE_TOAST, DEFAULT_RAC_MAX_VISIBLE_TOAST, DEFAULT_SCALE_FACTOR, DEFAULT_TOAST_TIMEOUT, DEFAULT_TOAST_WIDTH };
